window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6530d2fa02888eb8"]={"versions": [{"id": "FIG-6530d2fa02888eb8", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Notationelle Übersicht und Symbollegende für Diagrammelementtypen der AUTOSAR-Methodik auf Basis des SPEM 2.0-Standards (Software &amp; Systems Process Engineering Metamodel). Die Darstellung definiert die visuellen Stereotypen und Icon-Primitiven zur Modellierung von Methodik-Bibliothekselementen in prozessualen Schaubildern der AUTOSAR-Entwicklungsmethodik.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Übersicht umfasst sechs methodische Grundelemente mit ihren standardisierten grafischen Symbolen und Bezeichnungen:</p>\n<ul class=\"fig-list\"><li><strong>Role Definition</strong>: Durch eine stilisierte Personen-/Büstenfigur repräsentierte Entität, modelliert die für Aufgaben verantwortlichen oder beteiligten Entwickler- bzw. Prozessrollen.\n</li><li><strong>Task Definition</strong>: Als nach rechts weisender Blockpfeil dargestellte Entität, definiert eine zuweisbare Prozesseinheit bzw. Arbeitsschritt.\n</li><li><strong>Tool Definition</strong>: Als Hammer-Piktogramm symbolisierte Entität, modelliert softwarebasierte Werkzeuge oder automatisierte Toolketten zur Aufgabenunterstützung.\n</li><li><strong>Work Product Definition (Artifact)</strong>: Als Dokumentensymbol mit umgeknickter rechter oberer Ecke und horizontalen Textzeilen visualisiert, modelliert greifbare Zwischen- oder Endergebnisse wie XML-Beschreibungen, Modelle oder Quellcodedateien.\n</li><li><strong>Deliverable</strong>: Als Briefumschlagsymbol mit gestrichelten Linien an der linken Kante dargestellt (beschriftet mit „Deliverable¹“), repräsentiert formal auszuliefernde Work-Product-Bündel oder Meilensteinergebnisse.\n</li><li><strong>Guidance</strong>: Als L-förmiges Zeichendreieck/Messlineal-Piktogramm dargestellte Entität, definiert begleitende Richtlinien, Leitfäden oder methodische Anleitungen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Notationstabelle ohne Kontroll-, Datenfluss- oder Interaktionskanten. Die Elemente stehen nebeneinander als Referenzinventar für Prozessmodellierer; dynamische Abfolgen oder Work-Product-Übergaben ergeben sich erst bei Instanziierung in spezifischen SPEM-Methodik- und Prozessablaufdiagrammen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Notation der AUTOSAR Methodology Library zur einheitlichen visuellen Syntax in allen methodology-bezogenen AUTOSAR-Spezifikationen. Die Symbole dienen als verbindliche visuelle Entsprechungen der zugrundeliegenden SPEM-Metaklassen. Das Element „Deliverable“ verweist über die Fußnote 1 auf methodische Einschränkungen; „Guidance“ dient als vordefiniertes Bibliothekselement für zukünftige oder erweiternde Spezifikationskontexte.</p>"}, {"id": "FIG-617445ffd157733d", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Notationelle Übersicht und Symbollegende für Diagrammelementtypen der AUTOSAR-Methodik auf Basis des SPEM 2.0-Standards (Software &amp; Systems Process Engineering Metamodel). Die Darstellung definiert die visuellen Stereotypen und Icon-Primitiven zur Modellierung von Methodik-Bibliothekselementen in prozessualen Schaubildern der AUTOSAR-Entwicklungsmethodik.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Übersicht umfasst sechs methodische Grundelemente mit ihren standardisierten grafischen Symbolen und Bezeichnungen:</p>\n<ul class=\"fig-list\"><li><strong>Role Definition</strong>: Durch eine stilisierte Personen-/Büstenfigur repräsentierte Entität, modelliert die für Aufgaben verantwortlichen oder beteiligten Entwickler- bzw. Prozessrollen.\n</li><li><strong>Task Definition</strong>: Als nach rechts weisender Blockpfeil dargestellte Entität, definiert eine zuweisbare Prozesseinheit bzw. Arbeitsschritt.\n</li><li><strong>Tool Definition</strong>: Als Hammer-Piktogramm symbolisierte Entität, modelliert softwarebasierte Werkzeuge oder automatisierte Toolketten zur Aufgabenunterstützung.\n</li><li><strong>Work Product Definition (Artifact)</strong>: Als Dokumentensymbol mit umgeknickter rechter oberer Ecke und horizontalen Textzeilen visualisiert, modelliert greifbare Zwischen- oder Endergebnisse wie XML-Beschreibungen, Modelle oder Quellcodedateien.\n</li><li><strong>Deliverable</strong>: Als Briefumschlagsymbol mit gestrichelten Linien an der linken Kante dargestellt (beschriftet mit „Deliverable¹“), repräsentiert formal auszuliefernde Work-Product-Bündel oder Meilensteinergebnisse.\n</li><li><strong>Guidance</strong>: Als L-förmiges Zeichendreieck/Messlineal-Piktogramm dargestellte Entität, definiert begleitende Richtlinien, Leitfäden oder methodische Anleitungen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Notationstabelle ohne Kontroll-, Datenfluss- oder Interaktionskanten. Die Elemente stehen nebeneinander als Referenzinventar für Prozessmodellierer; dynamische Abfolgen oder Work-Product-Übergaben ergeben sich erst bei Instanziierung in spezifischen SPEM-Methodik- und Prozessablaufdiagrammen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Notation der AUTOSAR Methodology Library zur einheitlichen visuellen Syntax in allen methodology-bezogenen AUTOSAR-Spezifikationen. Die Symbole dienen als verbindliche visuelle Entsprechungen der zugrundeliegenden SPEM-Metaklassen. Das Element „Deliverable“ verweist über die Fußnote 1 auf methodische Einschränkungen; „Guidance“ dient als vordefiniertes Bibliothekselement für zukünftige oder erweiternde Spezifikationskontexte.</p>"}], "trans": [{"from": "FIG-6530d2fa02888eb8", "to": "FIG-617445ffd157733d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
